    {
      "card_ids": ["C26"],
      "claim": "Diflunisal, a salicylic acid derivative with two aromatic rings and a free carboxyl, has absolute bioavailability of 89.5% vs IV, supporting high F for the query's free-carboxyl, lipophilic structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "LAAM, a bulky diphenyl-substituted molecule with an ester and tertiary amine, has oral bioavailability of 47-48% in humans despite first-pass metabolism, supporting high F for the query's bulky diphenylmethyl ether.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "(S)-Methadone, a diphenyl-substituted drug, has absolute oral bioavailability of 0.88 ± 0.12 vs IV, supporting high F for the query's diphenyl-containing scaffold.",
      "evidence_role": "supportive"
    }
